#!/bin/bash
# zynthian package script for the @@NAME@@ LV2 plugin (zynthian-packages: @@CATEGORY@@/@@PACKAGE@@).
# Installs the bundle of the latest release built by the plugin's GitHub CI (x86_64 or arm64), and adds the plugin
# to the zynthian engines DB, enabled. webconf offers an update when a newer v* release is tagged: new versions
# don't need changes here.
# Generated by the zynthian-lv2-plugin skill.

REPO="@@SYMBOL@@"
GITHUB="@@GITHUB@@"
PLUGIN_URI="@@URI@@"

DIRNAME="$REPO.lv2"
REPO_URL="https://github.com/$GITHUB.git"
DST_DIR="${ZYNTHIAN_PLUGINS_DIR:-/zynthian/zynthian-plugins}/lv2"
SYS_DIR="${ZYNTHIAN_SYS_DIR:-/zynthian/zynthian-sys}"
UI_DIR="${ZYNTHIAN_UI_DIR:-/zynthian/zynthian-ui}"

case "${MACHINE_HW_NAME:-$(uname -m)}" in
    aarch64) CPU_ARCH="arm64" ;;
    x86_64) CPU_ARCH="x86_64" ;;
    *) CPU_ARCH="" ;;
esac
FILENAME="$REPO-lv2-$CPU_ARCH.tar.gz"
DOWNLOAD_URL="https://github.com/$GITHUB/releases/latest/download/$FILENAME"

# Is the plugin in the engines DB (0/1)? With "enable": enable it there (new plugins are added disabled).
engines_db() {
    ZYNTHIAN_UI_DIR="$UI_DIR" python3 - "$1" "$PLUGIN_URI" <<'PYEOF'
import importlib.util, logging, os, sys
logging.disable(logging.INFO)
spec = importlib.util.spec_from_file_location("zl", os.environ["ZYNTHIAN_UI_DIR"] + "/zyngine/zynthian_lv2.py")
zl = importlib.util.module_from_spec(spec)
spec.loader.exec_module(zl)
keys = [k for k, info in zl.engines.items() if info.get("URL") == sys.argv[2]]
if sys.argv[1] == "enable" and keys:
    for k in keys:
        zl.engines[k]["ENABLED"] = True
        zl.engines[k]["EDIT"] = max(1, zl.engines[k].get("EDIT", 0))  # user edit: regenerations keep it enabled
    zl.save_engines()
print(1 if keys else 0)
PYEOF
}

regenerate_engines_db() {
    ZYNTHIAN_SYS_DIR="$SYS_DIR" "$SYS_DIR/sbin/regenerate_engines_db.sh" >/dev/null 2>&1
    touch "${ZYNTHIAN_CONFIG_DIR:-/zynthian/config}/lv2.stamp"
}

do_install() {
    set -ex
    [ -n "$CPU_ARCH" ] || { echo "unsupported architecture: $(uname -m)"; exit 1; }
    mkdir -p "$DST_DIR"
    cd "$DST_DIR"
    wget -q -O "$FILENAME" "$DOWNLOAD_URL"
    rm -rf "$DIRNAME"
    tar xzf "$FILENAME"
    rm -f "$FILENAME"
    set +x
    # First install: add the plugin to the engines DB and enable it. Updates: it's already there.
    if [ "$(engines_db check)" != "1" ]; then
        regenerate_engines_db
        engines_db enable >/dev/null
    else
        touch "${ZYNTHIAN_CONFIG_DIR:-/zynthian/config}/lv2.stamp"
    fi
    echo "installed"
}

do_uninstall() {
    if [[ $(is_installed) == "installed" ]]; then
        rm -rf "$DST_DIR/$DIRNAME"
        regenerate_engines_db
        echo "uninstalled"
    else
        echo "not installed"
    fi
}

is_installed() {
    if [[ -d "$DST_DIR/$DIRNAME" ]]; then
        echo "installed"
    else
        echo "not installed"
    fi
}

git_repo() {
    echo $REPO_URL
}

# Version = newest v* release tag (webconf offers an update when it changes)
git_version() {
    git ls-remote --tags --refs "$REPO_URL" 'v*' | awk -F/ '{ print $3 }' | sort -V | tail -1
}

if [[ "$1" == "install" ]]; then
    do_install
elif [[ "$1" == "uninstall" ]]; then
    do_uninstall
elif [[ "$1" == "installed" ]]; then
    echo $(is_installed)
elif [[ "$1" == "git_version" ]]; then
    echo $(git_version)
elif [[ "$1" == "git_repo" ]]; then
    echo $(git_repo)
fi
